/**  命令处理结果（对应 JS handleCmd 的返回值，外加要落库的副作用） */
export type CmdOutcome = 
/**  不认识的命令 */
{ kind: "ignored" } | 
/**  入座 */
{ kind: "hello"; team_id: string | null } | 
/**  抢答（dup=true 表示重复被忽略） */
{ kind: "buzz"; dup: boolean; team_id: string | null } | 
/**  提交失败：队伍没有成员 */
{ kind: "answerNoStudent"; team_id: string | null } | 
/**  重复提交，已忽略 */
{ kind: "answerDuplicate"; sid: string } | 
/**  主观题：进待确认队列 */
{ kind: "answerPending"; sid: string } | 
/**  客观题：自动判分并记分 */
{ kind: "answerScored"; sid: string; result: string; points: number | null };

/**  一次命令处理的完整产物 */
export type CmdResult = {
	outcome: CmdOutcome,
	/**  要写进实时流的条目（按顺序插入，新的在前） */
	feeds: FeedItem[],
	/**  主观题待确认条目 */
	pending: Pending | null,
	/**  抢答条目（若发生） */
	buzz: Buzz | null,
	/**  记分请求（客观题才有） */
	score: ScoreRequest | null,
};

/**  实时流条目（教师端右上角滚动显示） */
